mapper.select:
SELECT version_label FROM product_label_versions
WHERE product_code = #{code}
AND id <> #{excludeId}

mapper.insert:
INSERT INTO product_label_versions (
    product_code, version_label, note, food_type, net_weight, ingredients_text, allergens,
    manufacture_report_no, packaging_material, shelf_life_months, shelf_life_unit, storage,
    layout, extra, is_current, created_at, created_by
)
SELECT product_code, #{versionLabel}, #{note, jdbcType=VARCHAR}, food_type, net_weight, ingredients_text, allergens,
       manufacture_report_no, packaging_material, shelf_life_months, shelf_life_unit, storage,
       layout, extra, 0, #{now}, #{who, jdbcType=VARCHAR}
  FROM product_label_versions
 WHERE id = #{fromId}

mapper.update:
UPDATE product_label_versions
food_type = #{foodType}, net_weight = #{netWeight}, ingredients_text = #{ingredientsText}, allergens = #{allergens}, manufacture_report_no = #{manufactureReportNo}, packaging_material = #{packagingMaterial}, shelf_life_months = #{shelfLifeMonths}, shelf_life_unit = #{shelfLifeUnit}, storage = COALESCE((SELECT sm.item_code FROM tb_common_code_item sm JOIN tb_common_code_group smg ON smg.common_code_group_id = sm.group_id AND smg.group_code = 'STORAGE_METHOD' JOIN tb_tenant smt ON smt.tenant_id = smg.tenant_id AND smt.tenant_code = 'SONGYEON' WHERE NULLIF(#{storage}, '') IS NOT NULL AND (sm.item_code = #{storage} OR sm.item_nm = #{storage} OR (split_part(sm.item_nm, '(', 1) <> '' AND strpos(#{storage}, split_part(sm.item_nm, '(', 1)) > 0)) ORDER BY CASE WHEN sm.item_code = #{storage} THEN 0 WHEN sm.item_nm = #{storage} THEN 1 ELSE 2 END, sm.sort_order, sm.item_code LIMIT 1), storage), layout = #{layoutJson}, extra = #{extraJson}, updated_at = #{now}, updated_by = #{who, jdbcType=VARCHAR}
WHERE id = #{id}
